<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Setting;use Illuminate\Http\Request;class SettingController extends Controller{public function edit(){foreach($this->defaults() as $key=>$meta)Setting::updateOrCreate(['key'=>$key],['label'=>$meta[0],'group'=>$meta[1]]);return view('admin.settings.edit',['items'=>Setting::orderBy('group')->orderBy('id')->get()]);}public function update(Request $r){$r->validate(['email'=>'nullable|email|max:255','map_embed_url'=>'nullable|url|max:2000','creative_url'=>'nullable|url|max:2000','vk_url'=>'nullable|url|max:2000']);foreach(Setting::all() as $item)$item->update(['value'=>$r->input($item->key)]);return back()->with('ok','Настройки сохранены');}private function defaults():array{return ['school_name'=>['Название школы','general'],'phone'=>['Телефон','contacts'],'email'=>['E-mail','contacts'],'address'=>['Основной адрес','contacts'],'legal_address'=>['Юридический адрес','requisites'],'inn'=>['ИНН','requisites'],'kpp'=>['КПП','requisites'],'ogrn'=>['ОГРН','requisites'],'okpo'=>['ОКПО','requisites'],'founder'=>['Учредитель','requisites'],'founder_representative'=>['Представитель учредителя','requisites'],'license_number'=>['Номер действующей лицензии','requisites'],'building_2_name'=>['Название второго корпуса','contacts'],'building_2_address'=>['Адрес второго корпуса','contacts'],'building_2_description'=>['Описание второго корпуса','contacts'],'working_hours'=>['Режим работы','contacts'],'map_embed_url'=>['Ссылка для карты','contacts'],'creative_url'=>['Сайт Школы креативных индустрий','links'],'vk_url'=>['ВКонтакте','links']];}}